import json, math, os, sys
sys.stdout.reconfigure(encoding='utf-8')
D = r'C:/Users/ADMIN/OneDrive/Desktop/AI_CAD/AI_Work/Thang-11/06-11-2026/521106-24'
W = D + '/work/specs'
TPL = r'C:/Users/ADMIN/OneDrive/Desktop/AI_CAD/Create_Flatten_SheetMetal-main/templates/Template.dxf'
ORDER = ['066371', '066372', '066373', '066374', '066375', '066376', '066377', '066378', '066379']
REDO = ['066376', '066377']
os.makedirs(W, exist_ok=True)


def read_ents(path):
    L = open(path, 'rb').read().decode('cp932').split('\r\n')
    i = L.index('ENTITIES'); j = L.index('ENDSEC', i)
    seg = L[i + 1:j - 1]
    out = []; cur = None
    for k in range(0, len(seg), 2):
        c, v = seg[k].strip(), seg[k + 1].strip()
        if c == '0':
